// Presentation simplification only: existing records and approval history stay intact.
let clarityStatus='all', clarityBusy=new Set();
function clarityPhase(t){return t.status==='بسته‌شده'?'done':t.status==='آماده بررسی'?'review':'open'}
function clarityLabel(t){return {open:'در دست انجام',review:'منتظر تأیید',done:'تمام‌شده'}[clarityPhase(t)]}
function clarityMine(t,i=me()){return t.owner===i||(t.collaborators||[]).includes(i)}
function clarityScope(v=view){return tasks.filter(t=>v!=='mine'||clarityMine(t))}
function clarityCanTick(t){return t.status==='بسته‌شده'?approvalAuthority(t):mayChangeTask(t)}
function clarityCheck(t){const phase=clarityPhase(t),checked=phase!=='open',allowed=clarityCanTick(t);return `<button type="button" class="task-tick ${phase}" role="checkbox" aria-checked="${checked}" aria-label="${esc(phase==='done'?'بازگشایی ':phase==='review'?'ادامهٔ ':'انجام شد: ')}${esc(t.title)}" data-tick="${esc(t.id)}" ${allowed&&!clarityBusy.has(t.id)?'':'disabled'} title="${esc(!allowed?'تغییر وضعیت فقط در اختیار مسئول و مدیریت مجاز است':phase==='done'?'بازگشایی با حفظ سوابق':phase==='review'?'ادامه کار و لغو ارسال':'انجام شد؛ ارسال آخرین نسخه برای تأیید')}">${checked?richIcon('check'):''}</button>`}
async function clarityToggle(id){const t=tasks.find(x=>x.id===id);if(!t||!clarityCanTick(t)||clarityBusy.has(id))return;clarityBusy.add(id);const actor=me(),rev=t.revision;renderTasks();try{if(t.status==='بسته‌شده'){reopenTask(t);toast('کار دوباره باز شد؛ سوابق محفوظ است.')}else if(t.status==='آماده بررسی'){changeSimpleStatus(t,'در حال انجام');toast('کار برای ادامه باز شد.')}else{await ensureDemoFiles(t);await importLinkedVersion(t);const versions=await taskVersions(t.id);if(me()!==actor||!tasks.includes(t)||t.revision!==rev)throw Error('کار به‌روز شده؛ دوباره تلاش کنید.');submitReview(t,versions.at(-1)?.id||null,versions);toast('انجام کار ثبت شد؛ منتظر تأیید '+people[t.assignedBy]);}}catch(e){toast(e.message||'ثبت انجام کار ممکن نشد.')}finally{clarityBusy.delete(id);render();}}
badge=function(t){return `<span class="pill clarity-${clarityPhase(t)}">${clarityLabel(t)}</span>`};
taskTable=function(list){if(!list.length)return empty('کاری در این بخش نیست.');return `<div class="clarity-table"><table><thead><tr><th>کار</th><th>مسئول</th><th>مهلت</th><th>وضعیت</th></tr></thead><tbody>${list.map(t=>`<tr data-rich-task="${esc(t.id)}" class="${clarityPhase(t)==='done'?'finished-row':''} ${selectedRichTask===t.id?'selected-row':''}"><td><div class="clarity-task-title">${clarityCheck(t)}<div><button class="task-title" data-task="${esc(t.id)}">${esc(t.title)}</button><div class="clarity-task-meta"><span dir="ltr">${taskCode(t)}</span>${t.demo||t.sample?'<span>نمونه</span>':''}${isCollaborator(t)&&t.owner!==me()?'<span>با همکاری شما</span>':''}${t.collaborators?.length?`<span>${num(t.collaborators.length)} همکار</span>`:''}${displayFileCount(t)?`<span>${richIcon('file')}${num(displayFileCount(t))}</span>`:''}</div></div></div></td><td>${person(t.owner)}</td><td><span class="${late(t)?'late':''}">${fmt(t.due)}</span>${late(t)?'<small class="late-label">گذشته از مهلت</small>':''}</td><td><div class="clarity-state">${badge(t)}${canContribute(t)&&t.status!=='بسته‌شده'?`<button class="row-upload" data-upload-task="${esc(t.id)}" aria-label="بارگذاری فایل برای ${esc(t.title)}">↑ بارگذاری فایل</button>`:''}${canApproveTask(t)?`<button class="approve-inline" data-quick-approve="${esc(t.id)}">تأیید نهایی</button>`:''}${t.status==='متوقف‌شده'?'<small>دارای مانع</small>':t.status==='نیازمند اصلاح'?'<small>اصلاح خواسته شده</small>':''}</div></td></tr>`).join('')}</tbody></table></div>`};
renderTasks=function(){const scope=clarityScope();let list=scope.filter(t=>(clarityStatus==='all'||clarityPhase(t)===clarityStatus)&&(!simpleQuery||(t.title+' '+t.description+' '+taskCode(t)).includes(simpleQuery))&&(!simpleOwner||t.owner===Number(simpleOwner)));list.sort((a,b)=>({open:0,review:1,done:2}[clarityPhase(a)]-{open:0,review:1,done:2}[clarityPhase(b)])||(a.due||'9999').localeCompare(b.due||'9999'));$('#workspace').innerHTML=`<div class="clarity-list-head"><div><h2>${view==='mine'?'کارهای من':'همهٔ کارهای پروژه'}</h2><p>${view==='mine'?'کارهایی که مسئول آن‌ها هستید یا در انجامشان همکاری دارید.':'همه در جریان کارند؛ تغییر هر کار با مسئول آن و مدیریت مجاز است.'}</p></div><span class="list-total">${num(scope.length)} کار</span></div><div class="clarity-tools"><div class="clarity-filters">${[['all','همه'],['open','در دست انجام'],['review','منتظر تأیید'],['done','تمام‌شده']].map(([v,label])=>`<button class="${clarityStatus===v?'active':''}" data-phase="${v}">${label}<span>${num(scope.filter(t=>v==='all'||clarityPhase(t)===v).length)}</span></button>`).join('')}</div><div class="clarity-search"><input id="claritySearch" placeholder="جست‌وجوی کار…" aria-label="جست‌وجوی کار" value="${esc(simpleQuery)}">${view==='all'?`<select id="clarityOwner" aria-label="فیلتر مسئول"><option value="">همه مسئول‌ها</option>${[...new Set(scope.map(t=>t.owner))].map(i=>`<option value="${i}" ${simpleOwner===String(i)?'selected':''}>${esc(people[i])}</option>`).join('')}</select>`:''}</div></div><div class="clarity-list">${taskTable(list)}</div><div class="clarity-list-foot"><span>تیک کنار کار = انجام شده و ارسال برای تأیید</span><span>${num(list.length)} کار در این نما</span></div>`;$('#workspace').querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{clarityStatus=b.dataset.phase;renderTasks()});$('#claritySearch').oninput=e=>{const p=e.target.selectionStart;simpleQuery=e.target.value;renderTasks();$('#claritySearch').focus();$('#claritySearch').setSelectionRange(p,p)};if($('#clarityOwner'))$('#clarityOwner').onchange=e=>{simpleOwner=e.target.value;renderTasks()};}
// One header for the workspace, with a project selector prepared for future projects.
const headerNode=$('header');headerNode.insertAdjacentHTML('afterbegin','<a class="clarity-brand" href="#" aria-label="سمندیس"><img src="samandis.jpg" alt="لوگوی سمندیس"><span>سمندیس<small>فضای مدیریت پروژه‌ها</small></span></a><details class="project-picker"><summary><span>پروژهٔ جاری</span><b>پروژه دارایی</b><i>⌄</i></summary><div><button id="currentProject">پروژه دارایی <span>فعال</span></button><p>پروژه‌های بعدی در همین فهرست قرار می‌گیرند.</p></div></details>');
$('#currentProject').onclick=()=>{$('.project-picker').open=false;navigate('mine')};
$('.content').insertAdjacentHTML('afterbegin',`<section class="project-hero"><div class="project-hero-copy"><span class="hero-eyebrow">شرکت سمندیس / تهران</span><h1>پروژه دارایی</h1><p>یک تصویر روشن از کارهای امروز،<br>یک قدم نزدیک‌تر به تحویل پروژه.</p><div class="hero-meta"><span><i></i> پروژه فعال</span><span>مدیر پروژه: رضا افشار</span></div><small>نمای نهایی پروژه · برگرفته از طرح معماری</small></div><div class="project-hero-image"><img src="project-facade.jpg" alt="تصویر نمای نهایی ساختمان دارایی تهران از طرح معماری"><span>ساختمان دارایی تهران</span></div></section><div class="clarity-nav"><div class="scope-tabs"><button data-scope="mine">کارهای من <b id="myTaskCount"></b></button><button data-scope="all">همه کارها <b id="allTaskCount"></b></button><button data-scope="program">برنامه پروژه</button></div><button class="primary" id="clarityAdd">＋ کار جدید</button></div>`);
$('#clarityAdd').onclick=()=>openSimpleEditor();document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>navigate(b.dataset.scope));
$('.header-tools').insertAdjacentHTML('afterbegin','<details class="clarity-management" id="clarityManagement"><summary>مدیریت ⌄</summary><div><button data-manage-view="members">اعضای پروژه</button><button data-manage-view="reports">گزارش افراد</button></div></details>');document.querySelectorAll('[data-manage-view]').forEach(b=>b.onclick=()=>{$('#clarityManagement').open=false;navigate(b.dataset.manageView)});
const clarityPreviousRender=render;render=function(){clarityPreviousRender();$('#clarityManagement').hidden=!manager();document.querySelectorAll('[data-scope]').forEach(b=>b.classList.toggle('active',b.dataset.scope===view));$('#myTaskCount').textContent=num(clarityScope('mine').length);$('#allTaskCount').textContent=num(tasks.length);$('#clarityAdd').hidden=!['mine','all'].includes(view);$('.role-label').firstChild.textContent='پنل آزمایشی ';};
const clarityPreviousNavigate=navigate;navigate=function(v){clarityStatus='all';simpleOwner='';clarityPreviousNavigate(v);};
const clarityPreviousDetail=detail;detail=async function(id){await clarityPreviousDetail(id);const t=tasks.find(t=>t.id===id);if(!t||!$('#details').open||selectedRichTask!==id)return;$('#sendForReview')?.replaceChildren(document.createTextNode('✓ انجام شد'));document.querySelectorAll('#detailBody [data-simple-status]').forEach(b=>{if(b.dataset.simpleStatus==='متوقف‌شده')b.remove();else if(t.status==='آماده بررسی')b.textContent='ادامه کار';else b.remove()});const candidate=$('#candidateVersion');if(candidate){const wrapper=document.createElement('details');wrapper.className='task-extra';const summary=document.createElement('summary');summary.textContent='انتخاب نسخه تحویل · پیش‌فرض: آخرین نسخه';candidate.closest('label').before(wrapper);wrapper.append(summary,candidate.closest('label'));}const files=$('#detailBody .task-section');if(files)files.querySelectorAll('.version-card').forEach((v,i,all)=>{if(i<all.length-1){let history=files.querySelector('.earlier-files');if(!history){history=document.createElement('details');history.className='earlier-files task-extra';history.innerHTML='<summary>نسخه‌های قبلی · محفوظ در سوابق</summary>';files.querySelector('h3').after(history)}history.append(v)}});};
document.addEventListener('click',async e=>{const tick=e.target.closest('[data-tick]');if(tick){e.preventDefault();await clarityToggle(tick.dataset.tick);return}const approve=e.target.closest('[data-quick-approve]');if(approve){const t=tasks.find(t=>t.id===approve.dataset.quickApprove);if(!t)return;try{approveTask(t);render();toast('کار تأیید نهایی شد.')}catch(err){toast(err.message)}}});
// Profiles remain a demo selector; switching never changes stored task ownership.
$('#person').addEventListener('change',()=>{clarityStatus='all';simpleOwner='';view='mine';render()});
view='mine';render();

// Upload is part of the assigned task, beside its completion control.
const attachmentDetail=detail;
detail=async function(id){
 await attachmentDetail(id);
 const t=tasks.find(x=>x.id===id);
 if(!t||selectedRichTask!==id||!$('#details').open)return;
 const form=$('#versionForm');
 if(form){
  form.classList.add('task-upload-panel');
  const disclosure=form.querySelector('details');if(disclosure)disclosure.open=true;
  const summary=form.querySelector('summary');if(summary)summary.textContent='بارگذاری فایل این کار';
  const input=$('#taskFiles');input.closest('label').classList.add('task-file-picker');
  const label=form.querySelector('[name="label"]');label.placeholder='اختیاری · مثلاً نقشه اصلاح‌شده';
  $('#uploadVersion').textContent='بارگذاری و ثبت فایل';
  input.onchange=()=>{
   let preview=form.querySelector('.upload-selection');
   if(!preview){preview=document.createElement('div');preview.className='upload-selection';input.closest('label').after(preview)}
   preview.textContent=Array.from(input.files).map(f=>f.name+' · '+sizeText(f.size)).join(' / ');
  };
 }
};
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-upload-task]');if(!b)return;
 const id=b.dataset.uploadTask;await detail(id);
 if(selectedRichTask!==id)return;
 const form=$('#versionForm');if(form){form.scrollIntoView({behavior:'smooth',block:'center'});$('#taskFiles').focus({preventScroll:true})}
});
// Counts reflect newly uploaded files as well as bundled sample attachments.
const attachmentAddVersion=addTaskVersion;
addTaskVersion=async function(t,files,label){const v=await attachmentAddVersion(t,files,label);const versions=await taskVersions(t.id);t.attachmentCount=versions.reduce((n,x)=>n+x.files.length,0);save();return v};
displayFileCount=function(t){return t.attachmentCount??t.demoVersions?.reduce((n,v)=>n+v.files.length,0)??0};
render();
